-- style: merge from DOLSharp (1741 candidate rows)
-- Strategy: stage in _tmp_style, then copy only rows whose natural key
-- (ID, ClassId) does not already exist in style.
-- Existing customisations stay untouched.

SET FOREIGN_KEY_CHECKS=0;
START TRANSACTION;

DROP TABLE IF EXISTS _tmp_style;
CREATE TABLE _tmp_style LIKE style;

-- Load DOLSharp rows into the staging table.

-- Merge: keep customisations — only insert rows whose (ID, ClassId) is new.
WHERE NOT EXISTS (SELECT 1 FROM style WHERE style.`ID` = _tmp_style.`ID` AND style.`ClassId` = _tmp_style.`ClassId`);

DROP TABLE _tmp_style;

COMMIT;
SET FOREIGN_KEY_CHECKS=1;

-- Done. Inserted only rows that were not already present.
